"""模拟机器狗：真实编码 H.264，再按厂家 24 字节头经 WebSocket 输出。

No physical cameras or motion commands are used.
"""
import argparse
import asyncio
import contextlib
import re
import struct
import time
from websockets.asyncio.server import serve
from websockets.exceptions import ConnectionClosed

HEADER = struct.Struct("!8sBBHIQ")
MAGIC = b"M20H264\x00"


class AccessUnits:
    """Split Annex-B at AUD NALs generated by x264 aud=1; keep SPS/PPS intact."""
    def __init__(self):
        self.buffer = bytearray()

    def feed(self, data):
        self.buffer.extend(data)
        if len(self.buffer) > 8 * 1024 * 1024:
            raise RuntimeError("模拟编码器未输出预期的 AUD 分隔符")
        starts = [m.start() for m in re.finditer(b"\x00\x00(?:\x00)?\x01", self.buffer)
                  if m.end() < len(self.buffer) and self.buffer[m.end()] & 31 == 9]
        if len(starts) < 2:
            return []
        packets = []
        offset = 0
        for boundary in starts[1:]:
            packets.append(bytes(self.buffer[offset:boundary]))
            offset = boundary
        del self.buffer[:offset]
        return packets


async def handle(ws, args):
    path = ws.request.path
    names = {"/front": 0, "/back": 1, **{f"/camera_{i}": i-1 for i in range(1, 5)}}
    if path not in names:
        await ws.close(1008, "use /camera_1 through /camera_4")
        return
    index = names[path]
    camera_id = 1 if index == 1 else 0
    # testsrc2 is unmistakably a generated test chart. UI also labels simulation.
    process = await asyncio.create_subprocess_exec(
        args.ffmpeg, "-hide_banner", "-loglevel", "error", "-nostdin", "-re",
        "-f", "lavfi", "-i", f"testsrc2=size=640x360:rate={args.fps}",
        "-vf", f"hue=h={index * 65},drawbox=x={20+index*140}:y=20:w=80:h=50:color=white:t=5",
        "-an", "-c:v", "libx264", "-preset", "ultrafast", "-tune", "zerolatency",
        "-threads", "1",
        "-profile:v", "baseline", "-pix_fmt", "yuv420p", "-bf", "0",
        "-g", str(args.fps), "-x264-params", "aud=1:repeat-headers=1",
        "-f", "h264", "pipe:1", stdout=asyncio.subprocess.PIPE,
        stderr=asyncio.subprocess.DEVNULL)
    splitter = AccessUnits()
    seq = 0
    try:
        while True:
            data = await process.stdout.read(65536)
            if not data:
                raise RuntimeError("模拟 FFmpeg 退出，请检查 libx264 支持")
            for payload in splitter.feed(data):
                header = HEADER.pack(MAGIC, 1, camera_id, 0, seq & 0xffffffff, time.time_ns() // 1000)
                await ws.send(header + payload)
                seq += 1
    except (ConnectionClosed, RuntimeError):
        pass
    finally:
        if process.returncode is None:
            with contextlib.suppress(ProcessLookupError):
                process.terminate()
            try:
                await asyncio.wait_for(process.wait(), 3)
            except asyncio.TimeoutError:
                process.kill()
                await process.wait()


async def main(args):
    async with serve(lambda ws: handle(ws, args), "127.0.0.1", args.port, compression=None):
        print(f"四路模拟 WebSocket 已启动：127.0.0.1:{args.port}/camera_1~camera_4，非实物", flush=True)
        await asyncio.Future()


if __name__ == "__main__":
    p = argparse.ArgumentParser()
    p.add_argument("--port", type=int, default=28765)
    p.add_argument("--fps", type=int, default=25)
    p.add_argument("--ffmpeg", default="ffmpeg")
    try:
        asyncio.run(main(p.parse_args()))
    except KeyboardInterrupt:
        pass
